insert into plant_patterns.media(code,original_name,storage_large,organ_id,caption_fr,author,license,publication_status) select 'PP-FL-'||b,b||'.JPG',nullif(u,''),(select id from plant_patterns.organs where code='fleur'),n,'William Cinéa','© William Cinéa',case when u<>'' then 'published' else 'draft' end from _f on conflict (code) do nothing;
insert into plant_patterns.observations(code,organ_id,status) select 'PP-FLOBS-'||b,(select id from plant_patterns.organs where code='fleur'),'a_identifier' from _f on conflict (code) do nothing;
insert into plant_patterns.evidence(media_id,observation_id) select m.id,o.id from _f f join plant_patterns.media m on m.code='PP-FL-'||f.b join plant_patterns.observations o on o.code='PP-FLOBS-'||f.b;
insert into plant_patterns.identification_proposals(observation_id,proposed_family,author,rationale,confidence,status) select o.id,f.f,'Pl@ntNet','Pl@ntNet '||f.s||'% '||coalesce(f.n,''),f.c,'proposee' from _f f join plant_patterns.observations o on o.code='PP-FLOBS-'||f.b;
insert into plant_patterns.media_projects(media_id,project) select m.id,'plant_patterns' from _f f join plant_patterns.media m on m.code='PP-FL-'||f.b on conflict do nothing;
